declare(strict_types=1);require_once __DIR__.'/auth.php';cal_auth_start();if(!cal_auth_ready()){header('Location: setup.php');exit;}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){if(cal_auth_login((string)($_POST['identity']??''),(string)($_POST['password']??''))){$next=(string)($_GET['next']??'index.php');if(str_contains($next,'://')||str_starts_with($next,'//'))$next='index.php';header('Location: '.$next);exit;}$error='Anmeldung fehlgeschlagen.';}?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>easyITCalendar Anmeldung</title><style>body{font:16px system-ui;background:#eef3f8;margin:0}.card{max-width:430px;margin:8vh auto;background:#fff;border:1px solid #ccd6e1;border-top:6px solid #0b4f8a;border-radius:12px;padding:1.4rem}label{display:grid;gap:.35rem;margin:1rem 0;font-weight:700}input{padding:.7rem;border:1px solid #abb8c5;border-radius:6px;font:inherit;width:100%;box-sizing:border-box}button{padding:.7rem 1rem;background:#0b4f8a;color:#fff;border:0;border-radius:6px;font-weight:800}.err{color:#a11}</style></head><body><main class="card"><h1>easyITCalendar</h1><p>Anmeldung für Kalender und Verwaltung.</p><?php if($error):?><p class="err"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post"><label>Benutzername oder E-Mail<input name="identity" required autofocus></label><label>Kennwort<input type="password" name="password" required></label><button>Anmelden</button></form></main></body></html>
